        require(address(this).balance >= amount);

        // Deposit at least MinSum, unlock time = current timestamp
        c.Put{value: amount}(0);

        uint balBefore = c.Acc(address(this)).balance;
        uint ethBefore = address(c).balance;

        // One block has passed by the time of a subsequent call in practice;
        // ensure unlockTime is strictly in the past by depositing with 0 delta
