        uint ethAfter = address(c).balance;

        assert(
            !reverted &&
            balBefore >= collectAm &&
            balAfter <= balBefore &&
            (balBefore - balAfter == collectAm || balAfter == balBefore) &&
            ethAfter <= ethBefore
        );
    }

    receive() external payable {}
}

